bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 61
test "$(docker ps --filter label=com.docker.compose.project=gace-createvdobot --filter label=com.docker.compose.service=videobot-poll -q | wc -l)" -eq 1 || exit 62
docker exec "$cid" sh -c 'command -v ffmpeg >/dev/null && command -v ffprobe >/dev/null' || exit 63
docker exec "$cid" sh -c 'test -d /var/lib/videobot/media-work && test -w /var/lib/videobot/media-work' || exit 64
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'JS'
import pg from 'pg';import {readFileSync} from 'node:fs';
const e=process.env,db=new pg.Pool({host:e.VIDEOBOT_DB_HOST,database:e.VIDEOBOT_DB_NAME,user:e.VIDEOBOT_DB_USER,password:readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1,connectionTimeoutMillis:5000});
try{
const q=await db.query("SELECT l.seller_user_id,l.thumbnail_file_id,l.sample_file_id,l.price_stars,l.paid_video_file_id FROM videobot_post_receipts a JOIN videobot_listings l ON l.listing_id=a.listing_id WHERE a.paid_message_id=4691 AND a.free_message_ids=ARRAY[4689,4690]::bigint[]");
if(q.rowCount!==1)process.exitCode=71;
else{
const r=q.rows[0];
if(!(Number(r.seller_user_id)>0 && typeof r.thumbnail_file_id==='string' && r.thumbnail_file_id.length>5 && typeof r.sample_file_id==='string' && r.sample_file_id.length>5 && typeof r.paid_video_file_id==='string' && Number.isInteger(r.price_stars)))process.exitCode=72;
else console.log('VIDEO_ALBUM_SOURCE_FILES_AND_SELLER_ELIGIBLE=PASS');
}
}catch{process.exitCode=79}finally{await db.end()}
JS
echo VIDEO_ALBUM_MEDIA_PIPELINE_PREFLIGHT=PASS
